package kr.memorynotes;
import android.content.*;import android.database.Cursor;import android.graphics.pdf.PdfRenderer;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.OpenableColumns;
import org.json.*;import java.io.*;import java.security.*;import java.util.*;
/** Streamed originals, persistent URI access, content identity and storage conversion. */
public final class PdfDocuments {
 public static ParcelFileDescriptor open(MainActivity a,File folder,JSONObject doc)throws Exception{if(doc.has("uri")){ParcelFileDescriptor fd=a.getContentResolver().openFileDescriptor(Uri.parse(doc.getString("uri")),"r");if(fd==null)throw new IOException("연결된 원본을 열 수 없습니다. 문서 관리에서 다시 연결해 주세요.");return fd;}return ParcelFileDescriptor.open(new File(folder,doc.getString("id")+".pdf"),ParcelFileDescriptor.MODE_READ_ONLY);}
 public static InputStream input(MainActivity a,File folder,JSONObject doc)throws Exception{if(doc.has("uri")){InputStream in=a.getContentResolver().openInputStream(Uri.parse(doc.getString("uri")));if(in==null)throw new IOException("원본 파일을 읽을 수 없습니다.");return in;}return new FileInputStream(new File(folder,doc.getString("id")+".pdf"));}
 static String hash(InputStream in,OutputStream out,long[] bytes)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] b=new byte[65536];int n;long total=0;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();md.update(b,0,n);if(out!=null)out.write(b,0,n);total+=n;}bytes[0]=total;StringBuilder s=new StringBuilder();for(byte x:md.digest())s.append(String.format(Locale.US,"%02x",x&255));return s.toString();}
 static void pick(PdfStudy s,boolean link,String reconnect){s.a.getPreferences(0).edit().putBoolean("pdf_import_link",link).putString("pdf_reconnect",reconnect==null?"":reconnect).putString("pdf_subject",s.subject).putString("pdf_chapter",s.chapter).apply();s.a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/pdf").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),PdfStudy.REQUEST);}
 static void imported(final PdfStudy s,final Uri uri,final boolean link,final String reconnect){if(s.a.busy||s.metadataBlocked)return;if(s.screen==s.a.root&&!s.remember())return;final JSONArray snapshot;try{snapshot=new JSONArray(s.docs().toString());}catch(Exception e){s.a.error(e);return;}s.a.startBusy(link?"원본을 연결하고 중복을 확인하는 중…":"PDF를 복사하고 중복을 확인하는 중…");s.worker.execute(new Runnable(){public void run(){File temp=null;try{
   String name="PDF 문서";try(Cursor c=s.a.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}final String display=name;final String id=reconnect.isEmpty()?UUID.randomUUID().toString():reconnect;long[] bytes={0};String digest;
   if(!link)temp=new File(s.folder,id+".import-"+UUID.randomUUID());try(InputStream in=s.a.getContentResolver().openInputStream(uri);OutputStream out=link?null:new FileOutputStream(temp)){if(in==null)throw new IOException("PDF를 읽을 수 없습니다.");digest=hash(in,out,bytes);}
   final String sha=digest;final long length=bytes[0];final int pages;JSONObject source=new JSONObject().put("id",id).put("uri",uri.toString());try(ParcelFileDescriptor fd=link?open(s.a,s.folder,source):ParcelFileDescriptor.open(temp,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer pdf=new PdfRenderer(fd)){pages=pdf.getPageCount();}if(pages<1)throw new IOException("PDF에 페이지가 없습니다.");
   String duplicate="";for(int i=0;i<snapshot.length();i++){JSONObject d=snapshot.getJSONObject(i);String existing=d.optString("sha256");if(existing.isEmpty()||d.has("uri"))try(InputStream in=input(s.a,s.folder,d)){long[] size={0};existing=hash(in,null,size);d.put("sha256",existing).put("bytes",size[0]);}catch(Exception ignored){existing="";}if(!d.getString("id").equals(reconnect)&&sha.equals(existing)){duplicate=d.getString("id");break;}}
   final String duplicateId=duplicate;final File staged=temp;s.a.runOnUiThread(new Runnable(){public void run(){s.a.endBusy();if(s.destroyed){if(staged!=null)staged.delete();return;}try{
    if(!duplicateId.isEmpty()&&reconnect.isEmpty()){if(staged!=null)staged.delete();JSONObject prior=new JSONObject(s.state.toString());try{for(int i=0;i<snapshot.length();i++){JSONObject hashed=snapshot.getJSONObject(i),live=s.findDoc(hashed.getString("id"));if(live!=null&&hashed.has("sha256"))live.put("sha256",hashed.getString("sha256")).put("bytes",hashed.optLong("bytes"));}s.persist();}catch(Exception e){s.state=prior;s.doc=s.doc==null?null:s.findDoc(s.doc.optString("id"));throw e;}s.message("이미 추가한 PDF입니다. 기존 문서를 엽니다.");s.open(s.findDoc(duplicateId),-1);return;}
    JSONObject existing=reconnect.isEmpty()?null:s.findDoc(reconnect);if(existing!=null&&existing.optString("sha256").isEmpty())for(int i=0;i<snapshot.length();i++){JSONObject prior=snapshot.getJSONObject(i);if(reconnect.equals(prior.optString("id"))&&prior.has("sha256")){existing.put("sha256",prior.getString("sha256"));break;}}if(!reconnect.isEmpty()&&existing==null)throw new IOException("연결할 문서를 찾을 수 없습니다.");if(existing!=null&&!sha.equals(existing.optString("sha256"))){if(existing.optString("sha256").isEmpty())throw new IOException("기존 문서의 지문을 확인할 수 없어 교체하지 않았습니다. 원본을 다시 사용할 수 있게 한 뒤 연결해 주세요.");throw new IOException("기존 PDF와 내용이 다릅니다. 같은 원본 파일을 선택해 주세요.");}
    JSONObject before=new JSONObject(s.state.toString());File target=new File(s.folder,id+".pdf");boolean installed=false,committed=false;try{
     if(staged!=null){if(target.exists())throw new IOException("이미 앱에 복사된 문서입니다.");if(!staged.renameTo(target))throw new IOException("PDF 저장 실패");installed=true;}
     JSONObject item=existing==null?new JSONObject().put("id",id).put("name",display).put("page",0).put("current","").put("subject",s.subject).put("chapter",s.chapter):existing;item.put("pages",pages).put("bytes",length).put("sha256",sha);if(link)item.put("uri",uri.toString());else item.remove("uri");if(existing==null)s.docs().put(item);
     for(int i=0;i<snapshot.length();i++){JSONObject d=snapshot.getJSONObject(i),current=s.findDoc(d.getString("id"));if(current!=null&&d.has("sha256")&&!current.has("sha256"))current.put("sha256",d.getString("sha256")).put("bytes",d.optLong("bytes"));}
     s.persist();committed=true;if(link&&target.exists()&&!target.delete())s.message("연결 완료. 이전 복사본 정리는 다시 시도해 주세요.");s.open(item,-1);
    }catch(Exception e){if(!committed){s.state=before;s.doc=s.doc==null?null:s.findDoc(s.doc.optString("id"));if(installed)target.delete();}throw e;}
   }catch(Exception e){if(staged!=null)staged.delete();s.a.error(e);}}});
  }catch(final Exception e){if(temp!=null)temp.delete();s.a.runOnUiThread(new Runnable(){public void run(){s.a.endBusy();s.a.error(e);}});}}});}
}
